/* Pair.i 保存排序前的位置；C 返回的数组由调用方释放。 */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
typedef struct  {
    int v,i;
}
Pair;
int cmpPair(const void*a,const void*b) {
    int x=((const Pair*)a)->v,y=((const Pair*)b)->v;
    return (x>y)-(x<y);
}
/* Caller frees returned array; *returnSize must be 2. */
int* twoSum(int* nums,int numsSize,int target,int* returnSize) {
    Pair*p=malloc(sizeof(Pair)*numsSize);
    for(int i=0; i<numsSize; i++)p[i]=(Pair) {
        nums[i],i
    }
    ;
    qsort(p,numsSize,sizeof(Pair),cmpPair);
    int l=0,r=numsSize-1;
    while(l<r) {
        long long s=(long long)p[l].v+p[r].v;
        if(s==target) {
            int*out=malloc(2*sizeof(int));
            out[0]=p[l].i;
            out[1]=p[r].i;
            *returnSize=2;
            free(p);
            return out;
        }
        if(s<target)l++;
        else r--;
    }
    free(p);
    *returnSize=0;
    return NULL;
}
int main(void) {
    int n;
    scanf("%d",&n);
    int*a=malloc(n*sizeof(int));
    /* 排序后的两端和偏小就移动左端，偏大就移动右端，不漏掉可能的组合。 */
    for(int i=0; i<n; i++)scanf("%d",&a[i]);
    int target;
    scanf("%d",&target);
    int count=0;
    int*r=twoSum(a,n,target,&count);
    if(!r||count!=2||r[0]<0||r[1]<0||r[0]>=n||r[1]>=n||r[0]==r[1])return 3;
    /* 比较函数只返回大小关系；命中时返回 Pair 中保存的原下标。 */
    printf("%d %d\n",r[0],r[1]);
    free(r);
    free(a);
    return 0;
}

