    static class Fast  {
        private final byte[] b=new byte[65536];
        int p=0,n=0;
        int read()throws Exception {
            if(p>=n) {
                n=System.in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
